/** Two small worlds share touch controls, scoring and an honest local learning
 * record. Practice moves and missed drops never become scored answers. */
import {GAMES,gameById,gameForState,createGame,attemptMove,advanceGame,hintGame,loadGames,saveGames} from './playroom-engine.js';
import {renderMaterials,materialsArt} from './playroom-materials.js';
import {renderCare,careArt} from './playroom-care.js';
import {mountPlayroomParent} from './playroom-parent.js';
import {labCardArt} from './clue-lab-world.js';
const PIP='/prototypes/i3-family-landing/assets/pip.svg';
const GUIDE='fixforward.playroom.guide.v1';
const clueLabCard=()=>`<a class="pr-game-card clue-lab" href="#clue-lab"><div class="pr-card-art">${labCardArt()}<span class="pr-card-badge">TEST + DISCOVER</span></div><div class="pr-card-copy"><p class="pr-eyebrow">3 mysteries · Ages 7–12</p><h2>Pip’s Clue Lab</h2><p>Change a control. Test an idea. Follow the clues.</p><span class="pr-card-cta">Investigate <b aria-hidden="true">→</b></span></div></a>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const star='<svg viewBox="0 0 80 80" aria-hidden="true"><path d="m40 6 10 22 24 3-18 17 5 25-21-12-21 12 5-25L6 31l24-3z" fill="#f3c75e" stroke="#9b6a18" stroke-width="3"/><circle cx="33" cy="39" r="2.5" fill="#3d452e"/><circle cx="47" cy="39" r="2.5" fill="#3d452e"/><path d="M33 48q7 7 14 0" fill="none" stroke="#3d452e" stroke-width="3" stroke-linecap="round"/></svg>';

export function mountPlayroom(host,{route='games',onNavigate=()=>{},signal}={}){
  const doc=host.ownerDocument,win=doc.defaultView,controller=new win.AbortController();
  if(signal?.aborted)return()=>{};
  let storage;try{storage=win.localStorage;}catch{}
  let sessions=loadGames(storage),state=null,selected=null,result=null,overlay=null,opener=null,drag=null,ghost=null,parentCleanup=null;
  let disposed=false,paused=!!win.matchMedia?.('(prefers-reduced-motion: reduce)').matches,haptics=false,saveOK=!!storage,flashTimer=0,clickAfter=0,guideDone=false;
  const canVibrate=typeof win.navigator?.vibrate==='function';
  const game=()=>gameForState(state);
  const level=()=>game()?.levels[state.levelIndex];
  function save(){sessions=[...sessions.filter(s=>s.id!==state.id),state].slice(-20);saveOK=saveGames(storage,sessions);}
  function mode(child){doc.body.classList.toggle('playroom-child',child);doc.body.classList.toggle('playroom-motion-paused',child&&paused);}
  function top(back='games'){return `<nav class="pr-top" aria-label="Game navigation"><a href="#${back}">← ${back==='games'?'Games':'Workshop'}</a><div><button data-pr-guide>How to play</button><a href="#parents?view=playroom">For parents ↗</a></div></nav>`;}
  function hub(){mode(true);host.innerHTML=`<section class="pr-page pr-hub">${top('learn')}<header class="pr-hub-heading"><div><p class="pr-eyebrow">PIP’S PLAYROOM · AGES 7–12</p><h1>Little moves.<br> <em>Big discoveries.</em></h1><p>Pick a world. Try things. See what changes.</p></div><img src="${PIP}" alt="Pip the toaster" width="115" height="115"></header><div class="pr-game-cards">${clueLabCard()}${GAMES.map(g=>{const resume=[...sessions].reverse().find(s=>s.gameId===g.id&&s.status!=='complete'&&(s.contentVersion??1)===(g.contentVersion??1));return `<a class="pr-game-card ${g.id}" href="#play?game=${g.id}"><div class="pr-card-art">${g.id==='materials'?materialsArt():careArt()}<span class="pr-card-badge">${g.id==='materials'?'SORT + CREATE':'MOVE + DISCOVER'}</span></div><div class="pr-card-copy"><p class="pr-eyebrow">${g.levels.length} ${g.id==='care'?'rooms':'stages'} · At your pace</p><h2>${esc(g.title)}</h2><p>${g.id==='materials'?'Find the treasure. Choose the right next step.':'Give Pip’s rooms a little care.'}</p><span class="pr-card-cta">${resume?'Continue · '+resume.points+' Sparks':'Let’s play'} <b aria-hidden="true">→</b></span></div></a>`;}).join('')}<a class="pr-game-card workshop" href="#learn"><div class="pr-card-art pr-workshop-card"><img src="${PIP}" alt="" width="140" height="140"><span class="pr-card-orbit" aria-hidden="true">✦</span><span class="pr-card-badge">EXPLORE IN 3D</span></div><div class="pr-card-copy"><p class="pr-eyebrow">6 missions · At your pace</p><h2>Second-Life Workshop</h2><p>Find the next chapter for everyday things.</p><span class="pr-card-cta">Open the workshop <b aria-hidden="true">→</b></span></div></a></div><footer class="pr-hub-footer"><span>Test, discover or move things. Play at your pace.</span><a href="#parents?view=playroom">Our new discoveries ↗</a></footer></section>`;}
  function start(id,fresh=false){const g=gameById(id);if(!g){hub();return;}closePanel(false);state=(!fresh&&[...sessions].reverse().find(s=>s.gameId===id&&s.status!=='complete'&&(s.contentVersion??1)===(g.contentVersion??1)))||createGame(id);selected=null;result=null;save();renderGame();let seen=guideDone;try{seen ||=storage?.getItem(GUIDE)==='seen';}catch{}if(!seen)guide();}
  function renderGame(){cancelDrag();win.clearTimeout(flashTimer);mode(true);if(state.status==='complete'){finish();return;}
    const g=game(),l=level();host.innerHTML=`<section class="pr-page pr-game" data-game="${g.id}">${top()}<header class="pr-game-heading"><div><p class="pr-eyebrow">${esc(g.title)} · ${state.levelIndex+1} / ${g.levels.length}</p><h1>${esc(l.title)}</h1></div><button class="pr-help" data-pr-help>Help ?</button><div class="pr-sparks" aria-label="${state.points} Sparks"><span aria-hidden="true">✦</span> <b data-pr-points>${state.points}</b> Sparks</div></header><div class="pr-instruction"><img src="${PIP}" alt="Pip" width="42" height="42"><div><strong>${esc(l.instruction)}</strong><span>${esc(l.story)}</span></div><button data-pr-motion aria-pressed="${paused}" aria-label="Pause decorative motion">${paused?'Motion off':'Motion on'}</button></div><div class="pr-board-wrap"><div data-pr-board></div><div class="pr-flash" data-pr-flash hidden aria-hidden="true"></div></div><footer class="pr-feedback" data-pr-feedback role="status" aria-live="polite" aria-atomic="true"></footer><p data-pr-save class="pr-save" ${saveOK?'hidden':''}>Keep playing. Saving is unavailable in this browser.</p></section>`;drawBoard();drawFeedback();}
  // Positions stay stable within a round and vary on replay. The engine checks
  // item IDs, so a different layout never changes the learning rule or score.
  function varied(items,salt){return items.map(item=>{let n=2166136261;for(const c of state.id+salt+item.id)n=Math.imul(n^c.charCodeAt(0),16777619);return {item,n:n>>>0};}).sort((a,b)=>a.n-b.n).map(entry=>entry.item);}
  function drawBoard(){const board=host.querySelector('[data-pr-board]');if(!board)return;const authored=level(),visible=state.gameId==='materials'?{...authored,pieces:varied(authored.pieces,authored.id+'pieces'),targets:varied(authored.targets,authored.id+'targets')}:authored;board.innerHTML=(state.gameId==='materials'?renderMaterials:renderCare)({level:visible,completed:state.completed,selected,result});
    // Board modules draw only. The shell gives every game the same semantics.
    board.querySelectorAll('[data-piece]').forEach(b=>{const done=!!state.completed[b.dataset.piece];b.setAttribute('aria-pressed',String(selected===b.dataset.piece));b.disabled=done;b.classList.toggle('pr-selected',selected===b.dataset.piece);if(result?.pieceId===b.dataset.piece)b.classList.add(result.correct?'pr-right':'pr-wrong');});
    board.querySelectorAll('[data-target]').forEach(b=>{b.disabled=state.status!=='playing';});
  }
  function drawFeedback(){const f=host.querySelector('[data-pr-feedback]');if(!f)return;const done=state.status==='level-complete';host.querySelector('[data-pr-help]').disabled=done;const chosen=level().pieces.find(p=>p.id===selected);f.dataset.kind=result?.correct===true?'correct':result?.correct===false?'wrong':'neutral';f.innerHTML=`<span class="pr-result-icon" aria-hidden="true">${result?.correct===true?'✓':result?.correct===false?'✕':done?'✓':'↔'}</span><div><strong>${result?.correct===true?'You did it!':result?.correct===false?'Try another place.':done?'Stage complete!':chosen?`Now find a home for ${esc(chosen.label)}.`:'Tap an item. Then tap its home.'}</strong><p>${esc(result?.text||(chosen?'You can drag it there too.':'Or drag an item onto a labelled place.'))}</p></div>${done?`<button class="pr-button primary pr-next" data-pr-next>${state.levelIndex===game().levels.length-1?'My discoveries':'Next '+(state.gameId==='care'?'room':'stage')} →</button>`:''}${state.attempts.length>=500&&!done?'<button class="pr-button" data-pr-restart>Start a new round</button>':''}`;host.querySelector('[data-pr-points]').textContent=state.points;host.querySelector('.pr-sparks').setAttribute('aria-label',state.points+' Sparks');host.querySelector('[data-pr-save]').hidden=saveOK;}
  function choose(id){if(overlay||state?.status!=='playing'||state.completed[id])return;selected=id;result=null;drawBoard();drawFeedback();host.querySelector(`[data-piece="${id}"]`)?.focus({preventScroll:true});}
  function feedback(correct,text,points=0,pieceId=null,targetId=null){result={correct,text,points,pieceId,targetId};drawBoard();drawFeedback();const flash=host.querySelector('[data-pr-flash]');win.clearTimeout(flashTimer);flash.hidden=false;flash.dataset.kind=correct===true?'correct':correct===false?'wrong':'neutral';flash.innerHTML=`<span>${correct===true?'✓':correct===false?'✕':'↔'}</span><strong>${correct===true?'+'+points+' Sparks':correct===false?'Try again':'Find a home'}</strong>${correct===true?Array.from({length:9},(_,i)=>`<i style="--n:${i}" aria-hidden="true">✦</i>`).join(''):''}`;flashTimer=win.setTimeout(()=>{if(flash.isConnected)flash.hidden=true;},correct===null?1200:1550);if(correct!==null&&canVibrate&&haptics&&!paused)try{win.navigator.vibrate(correct?35:[40,30,40]);}catch{}}
  function move(pieceId,targetId){if(overlay||state?.status!=='playing')return;const answer=attemptMove(state,pieceId,targetId);if(!answer.accepted){if(answer.text)feedback(null,answer.text);return;}state=answer.state;selected=answer.correct?null:pieceId;save();feedback(answer.correct,answer.text,answer.points,pieceId,targetId);host.querySelector(state.status==='level-complete'?'[data-pr-next]':`[data-target="${targetId}"]`)?.focus({preventScroll:true});}
  function finish(){mode(true);const g=game();host.innerHTML=`<section class="pr-page pr-finish">${top()}<div class="pr-finish-content"><div class="pr-medal">${star}</div><p class="pr-eyebrow">${esc(g.title)} · COMPLETE</p><h1>${state.gameId==='care'?'Small care. Big difference.':'You rescued the possibilities!'}</h1><div class="pr-finish-points">✦ ${state.points} Sparks</div><div class="pr-discovery"><h2>What we discovered</h2><p>${esc(g.childLearning||g.learning)}</p><p><strong>Tell your grown-up:</strong> ${esc(g.childTalkPrompt||g.talkPrompt)}</p></div>${state.gameId==='materials'?`<div class="pr-learning-chain" aria-label="Keep learning together"><span class="is-done">1 · Discover ✓</span><span>2 · Choose what to do</span><span>3 · Act with an adult</span></div><div class="pr-finish-actions"><a class="pr-button primary" href="#learn?game=fix-it">Try Fix-it Station →</a><a class="pr-button" href="#action?kind=recycle">Grown-ups: take action ↗</a><a class="pr-button" href="#parents?view=playroom">Our learning</a><button class="pr-button" data-pr-restart>Play again</button></div>`:`<div class="pr-finish-actions"><a class="pr-button primary" href="#parents?view=playroom">Show my grown-up →</a><a class="pr-button" href="#games">Choose another game</a><button class="pr-button" data-pr-restart>Play again</button></div>`}<p class="pr-boundary">Pretend items here. Adult help for real appliances.</p></div></section>`;}
  function closePanel(restore=true){if(!overlay)return;cancelDrag();overlay.remove();overlay=null;host.querySelector('.pr-page')?.removeAttribute('inert');if(restore)(opener?.isConnected?opener:host.querySelector('[data-piece]:not(:disabled),[data-pr-guide]'))?.focus({preventScroll:true});opener=null;}
  function panel(html){cancelDrag();closePanel(false);opener=doc.activeElement;overlay=doc.createElement('div');overlay.className='pr-modal-cover';overlay.innerHTML=html;host.querySelector('.pr-page')?.setAttribute('inert','');host.append(overlay);overlay.querySelector('button')?.focus({preventScroll:true});}
  function guide(){panel(`<section class="pr-modal" role="dialog" aria-modal="true" aria-labelledby="pr-guide-title"><div class="pr-modal-top"><span>LET’S TRY IT</span><button data-pr-skip>Skip practice</button></div><h2 id="pr-guide-title">Give Pip a star.</h2><p data-pr-practice-note>Tap the star. Then tap Pip’s tray. Or drag it!</p><div class="pr-practice"><button data-pr-practice-piece aria-label="Practice star" aria-pressed="false">${star}</button><span aria-hidden="true">→</span><button data-pr-practice-target aria-label="Pip’s star tray"><img src="${PIP}" alt="" width="90" height="90"><b>Pip’s tray</b></button></div><p class="pr-guide-meaning"><b>✓</b> A useful move! <b>✕</b> Try another place.</p><button class="pr-button primary" data-pr-ready disabled>Move the star first</button>${canVibrate?`<button class="pr-haptics" data-pr-haptics aria-pressed="${haptics}">Vibration ${haptics?'on':'off'}</button>`:''}</section>`);}
  function practiceSelect(){const piece=overlay?.querySelector('[data-pr-practice-piece]');if(piece){piece.setAttribute('aria-pressed','true');overlay.querySelector('[data-pr-practice-note]').textContent='Now tap Pip’s tray.';}}
  function practiceDone(){if(!overlay)return;overlay.querySelector('[data-pr-practice-piece]').disabled=true;overlay.querySelector('[data-pr-practice-target]').classList.add('pr-practice-done');overlay.querySelector('[data-pr-practice-note]').textContent='You did it! After each stage, tap Next. Help gives a clue.';const next=overlay.querySelector('[data-pr-ready]');next.disabled=false;next.textContent=state?'Let’s play →':'Choose a game →';next.focus({preventScroll:true});}
  function endGuide(){guideDone=true;try{storage?.setItem(GUIDE,'seen');}catch{}closePanel();}
  function help(){if(!state||state.status!=='playing')return;state=hintGame(state);save();panel(`<section class="pr-modal" role="dialog" aria-modal="true" aria-labelledby="pr-help-title"><img src="${PIP}" width="80" height="80" alt="Pip"><h2 id="pr-help-title">Here’s a clue</h2><p>${esc(level().help)}</p><p class="pr-help-small">A useful move earns 10 Sparks. A first try without help adds 5. Help is always OK.</p><button class="pr-button primary" data-pr-close>Got it →</button></section>`);}
  host.addEventListener('click',e=>{if(Date.now()<clickAfter)return;const b=e.target.closest('button');if(!b)return;
    if(overlay){if(b.matches('[data-pr-skip],[data-pr-ready]')&&!b.disabled)endGuide();else if(b.matches('[data-pr-close]'))closePanel();else if(b.matches('[data-pr-practice-piece]'))practiceSelect();else if(b.matches('[data-pr-practice-target]')&&overlay.querySelector('[data-pr-practice-piece]').getAttribute('aria-pressed')==='true')practiceDone();else if(b.matches('[data-pr-haptics]')){haptics=!haptics;b.setAttribute('aria-pressed',haptics);b.textContent='Vibration '+(haptics?'on':'off');if(!haptics)stopHaptics();}return;}
    if(b.matches('[data-piece]'))choose(b.dataset.piece);
    else if(b.matches('[data-target]')){if(selected)move(selected,b.dataset.target);else feedback(null,'Choose an item first, then tap its home.');}
    else if(b.matches('[data-pr-next]')&&state.status==='level-complete'){state=advanceGame(state);selected=null;result=null;save();renderGame();host.querySelector('h1')?.setAttribute('tabindex','-1');host.querySelector('h1')?.focus({preventScroll:true});}
    else if(b.matches('[data-pr-restart]'))start(state.gameId,true);
    else if(b.matches('[data-pr-guide]'))guide();
    else if(b.matches('[data-pr-help]'))help();
    else if(b.matches('[data-pr-motion]')){paused=!paused;mode(true);b.setAttribute('aria-pressed',paused);b.textContent=paused?'Motion off':'Motion on';if(paused)stopHaptics();}
  },{signal:controller.signal});
  // The visible clone follows the finger; the original stays in layout. A small
  // movement threshold separates taps from drags and preserves keyboard play.
  host.addEventListener('pointerdown',e=>{if(e.isPrimary===false||e.button>0)return;const b=e.target.closest('[data-piece],[data-pr-practice-piece]');if(!b||b.disabled||drag||overlay&&!overlay.contains(b))return;drag={id:e.pointerId,node:b,x:e.clientX,y:e.clientY,moved:false,practice:b.hasAttribute('data-pr-practice-piece')};try{b.setPointerCapture(e.pointerId);}catch{}},{signal:controller.signal});
  host.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.moved&&Math.hypot(dx,dy)<7)return;e.preventDefault();if(!drag.moved){drag.moved=true;const r=drag.node.getBoundingClientRect();ghost=drag.node.cloneNode(true);ghost.removeAttribute('data-piece');ghost.removeAttribute('data-pr-practice-piece');ghost.setAttribute('aria-hidden','true');ghost.classList.add('pr-drag-ghost');Object.assign(ghost.style,{position:'fixed',left:r.left+'px',top:r.top+'px',width:r.width+'px',height:r.height+'px',margin:'0',pointerEvents:'none',zIndex:'1001'});doc.body.append(ghost);drag.node.classList.add('pr-drag-origin');}ghost.style.transform=`translate(${dx}px,${dy}px) scale(1.05)`;},{signal:controller.signal,passive:false});
  host.addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;const d=drag;if(!d.moved){cancelDrag();return;}const target=doc.elementFromPoint?.(e.clientX,e.clientY)?.closest(d.practice?'[data-pr-practice-target]':'[data-target]');cancelDrag();clickAfter=Date.now()+350;if(d.practice){if(target&&overlay?.contains(target))practiceDone();else if(overlay)overlay.querySelector('[data-pr-practice-note]').textContent='Try dropping the star onto Pip’s tray.';}else if(target&&host.contains(target))move(d.node.dataset.piece,target.dataset.target);else feedback(null,'That missed the place. Try again, or tap an item then its home.');},{signal:controller.signal});
  function cancelDrag(){const old=drag;drag=null;if(old){old.node.classList.remove('pr-drag-origin');try{old.node.releasePointerCapture(old.id);}catch{}}ghost?.remove();ghost=null;}
  function stopHaptics(){if(canVibrate)try{win.navigator.vibrate(0);}catch{}}
  host.addEventListener('pointercancel',cancelDrag,{signal:controller.signal});
  host.addEventListener('lostpointercapture',e=>{if(drag?.id===e.pointerId)cancelDrag();},{signal:controller.signal});
  win.addEventListener('blur',()=>{cancelDrag();stopHaptics();},{signal:controller.signal});
  host.addEventListener('keydown',e=>{if(!overlay)return;if(e.key==='Escape'){e.preventDefault();if(overlay.querySelector('[data-pr-ready]'))endGuide();else closePanel();return;}if(e.key==='Tab'){const buttons=[...overlay.querySelectorAll('button:not(:disabled),a[href]')],first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&doc.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&doc.activeElement===last){e.preventDefault();first.focus();}}},{signal:controller.signal});
  function cleanup(){if(disposed)return;disposed=true;closePanel(false);cancelDrag();stopHaptics();win.clearTimeout(flashTimer);parentCleanup?.();controller.abort();signal?.removeEventListener('abort',cleanup);mode(false);}
  signal?.addEventListener('abort',cleanup,{once:true});
  if(route.split('?')[0]==='parents'){mode(false);parentCleanup=mountPlayroomParent(host,{onNavigate,storage});}
  else if(route.split('?')[0]==='play'){start(new URLSearchParams(route.split('?')[1]||'').get('game')||'materials');}
  else hub();
  return cleanup;
}
